class ApiClient(engine: HttpClientEngine) {
    private val http = HttpClient(engine) { install(ContentNegotiation) { json() } }
    suspend fun price(sku: String): PriceResponse = http.get("https://api/prices/$sku").body()
}

val mockEngine = MockEngine { respond("""{"price":9.99}""", headers = headersOf(HttpHeaders.ContentType, "application/json")) }
val client = ApiClient(mockEngine)
